curl --request POST \
  --url https://api.aisa.one/apis/v1/firecrawl-alexandria/aer-ca/energy-regulator-decisions-directives-notices/get_bulletin \
  --header 'Authorization: Bearer <token>' \
  --header 'Content-Type: application/json' \
  --data '{
  "alexandria": {
    "provider": "aer-ca",
    "capability": "energy-regulator-decisions-directives-notices/get_bulletin",
    "options": {
      "request": {
        "number": "2026-42"
      },
      "response": {
        "body_text": "Today, we published a revised edition of Directive 068: Security Deposits.\nWe made the following revisions to the directive:\nAdded guidance regarding security deposits for new or amended oilfield waste management facility applications (section 3.1.3).\nRevised the notice period for nonrenewal and cancellation of letters of credit from 60 days to 90 days (section 4.2).\nAdded demand forfeiture bonds (DFBs) to the list of acceptable forms of security (section 4.3). We will now accept surety bonds in the form of an AER-approved DFB from licensees of oil, gas, geothermal, and brine-hosted mineral developments.\nRevised how interest accrued from a cash security deposit is refunded (section 7).\nRemoved references to monthly bank statements.\nThe AER-approved DFB is the only form of surety bond accepted by the AER. The DFB will be available on our liability management forms webpage. We will only accept it without alteration.\nWe will only accept surety from providers with active operations in Canada and an A rating (or equivalent) from a credit-rating agency acceptable to the AER.\nThe revised edition of Directive 068 is available on the directive landing page.\nDirect any questions regarding security deposits to Directive068@aer.ca. All other questions can be directed to our Customer Contact Centre by phone at 403-297-8311 (1-855-297-8311 toll free) or by email at inquiries@aer.ca.",
        "links": [
          {
            "text": "Directive 068: Security Deposits",
            "url": "https://www.aer.ca/regulations-and-compliance-enforcement/rules-and-regulations/directives/directive-068"
          },
          {
            "text": "liability management forms",
            "url": "https://www.aer.ca/applications-and-notices/application-processes/aer-forms/liability-management-forms"
          },
          {
            "text": "directive landing page",
            "url": "https://www.aer.ca/regulations-and-compliance-enforcement/rules-and-regulations/directives/directive-068"
          }
        ],
        "number": "2026-42",
        "observed_at_ms": 1791923429946,
        "pdf_url": "https://www.aer.ca/prd/documents/bulletins/Bulletin-2026-42.pdf",
        "related_directives": [
          {
            "number": "068",
            "url": "https://www.aer.ca/regulations-and-compliance-enforcement/rules-and-regulations/directives/directive-068"
          }
        ],
        "release_date": "2026-10-08",
        "slug": "bulletin-2026-42",
        "subtitle": "Revised Edition of Directive 068",
        "title": "Bulletin 2026-42",
        "url": "https://www.aer.ca/about-aer/media-centre/bulletins/bulletin-2026-42"
      },
      "recordedAt": "2026-10-13"
    }
  },
  "zeroDataRetention": false
}'

