  --data '{
  "alexandria": {
    "provider": "aer-ca",
    "capability": "energy-regulator-decisions-directives-notices/get_directive",
    "options": {
      "request": {
        "number": "001"
      },
      "response": {
        "body_text": "Replaces the previous edition released on July 4, 2023.\nReleased with Bulletin 2025-04.\nSee section 1.3 of the directive for what’s new.\nPurpose of this Directive\nThis directive sets out the requirements for completing and submitting a site-specific liability assessment (SSLA). These directive applies to all liability management programs administered under the Oil and Gas Conservation Rules, Brine-Hosted Mineral Resource Development Rules, and Geothermal Resource Development Rules. It does not apply to sites subject to liability management programs administered under the specified enactments (e.g., the Mine Financial Security Program, which is authorized under the Environmental Protection and Enhancement Act).\nThe aim of this directive is to improve the consistency and accuracy of liability assessments submitted to the AER. They do not modify requirements on how to provide reasonable care and measures, contamination management (including remediation), suspension, abandonment, and reclamation activities.\nForms and Attachments\nDirective 001 Forms\nWhat We Heard",
        "effective_date": "2025-02-07",
        "links": [
          {
            "text": "Bulletin 2025-04",
            "url": "https://www.aer.ca/about-aer/media-centre/bulletins/bulletin-2025-04"
          },
          {
            "text": "Oil and Gas Conservation Rules",
            "url": "https://open.alberta.ca/publications/1971_151"
          },
          {
            "text": "Brine-Hosted Mineral Resource Development Rules",
            "url": "https://open.alberta.ca/publications/2023_017"
          },
          {
            "text": "Geothermal Resource Development Rules",
            "url": "https://open.alberta.ca/publications/2022_116"
          },
          {
            "text": "Directive 001 Forms",
            "url": "https://www.aer.ca/node/183#directive001"
          },
          {
            "text": "What We Heard",
            "url": "https://www.aer.ca/media/13998"
          }
        ],
        "number": "001",
        "observed_at_ms": 1791923389515,
        "pdf_url": "https://www.aer.ca/documents/directives/Directive001.pdf",
        "release_date": "2025-02-07",
        "released_with_bulletin": "2025-04",
        "slug": "directive-001",
        "subtitle": "Requirements for Site-Specific Liability Assessments",
        "title": "Directive 001",
        "url": "https://www.aer.ca/regulations-and-compliance-enforcement/rules-and-regulations/directives/directive-001"
      },
      "recordedAt": "2026-10-13"
    }
  },
  "zeroDataRetention": false
}'

